import numpy as np, heapq, json
from PIL import Image
from scipy.ndimage import distance_transform_edt, gaussian_filter
im=np.array(Image.open('/app/target.png').convert('RGB')); mask=np.min(im,2)<80; p=np.pad(mask,1)
for it in range(1000):
 anyrem=False
 for sub in (0,1):
  a=p[1:-1,1:-1]; n=[p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]]
  cnt=sum(n); tr=sum((n[j]==0)&(n[(j+1)%8]==1) for j in range(8))
  cond=(n[0]*n[2]*n[4]==0)&(n[2]*n[4]*n[6]==0) if sub==0 else (n[0]*n[2]*n[6]==0)&(n[0]*n[4]*n[6]==0)
  rm=a&(cnt>=2)&(cnt<=6)&(tr==1)&cond
  if rm.any(): p[1:-1,1:-1][rm]=0; anyrem=True
 if not anyrem: break
sk=p[1:-1,1:-1]; D=distance_transform_edt(mask); h,w=sk.shape

def nearest(pt):
 x,y=pt; ys,xs=np.where(sk[max(0,y-12):min(h,y+13),max(0,x-12):min(w,x+13)])
 xs=xs+max(0,x-12); ys=ys+max(0,y-12); i=np.argmin((xs-x)**2+(ys-y)**2); return (int(xs[i]),int(ys[i]))

def astar(a,b):
 a=nearest(a); b=nearest(b); q=[(0,0,a)]; dist={a:0.}; prev={}; visited=set()
 while q:
  _,g,u=heapq.heappop(q)
  if u in visited: continue
  visited.add(u)
  if u==b: break
  x,y=u
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if not(dx or dy): continue
    xx,yy=x+dx,y+dy
    if not(0<=xx<w and 0<=yy<h and sk[yy,xx]): continue
    ng=g+(1.41421356 if dx and dy else 1.)
    if ng<dist.get((xx,yy),1e9):
     dist[(xx,yy)]=ng; prev[(xx,yy)]=u
     heuristic=np.hypot(xx-b[0],yy-b[1]); heapq.heappush(q,(ng+heuristic,ng,(xx,yy)))
 if b not in prev and a!=b: raise RuntimeError((a,b))
 path=[b]
 while path[-1]!=a: path.append(prev[path[-1]])
 return np.array(path[::-1],float)

def resample(path,step=12):
 ds=np.r_[0,np.cumsum(np.linalg.norm(np.diff(path,axis=0),axis=1))]; total=ds[-1]; ts=np.arange(0,total,step); ts=np.r_[ts,total]
 out=[]
 for t in ts:
  j=np.searchsorted(ds,t); j=min(max(1,j),len(ds)-1); a,b=path[j-1],path[j]; f=(t-ds[j-1])/(ds[j]-ds[j-1]+1e-9); out.append(a*(1-f)+b*f)
 return np.array(out)
paths={
'left_h':((248,445),(450,414)),
'left_v':((353,249),(362,745)),
'left_downleft':((365,477),(217,671)),
'left_downright':((379,488),(433,529)),
'right_h':((493,419),(717,379)),
'right_v':((570,224),(582,771)),
'right_downleft':((582,456),(430,648)),
'right_downright':((608,456),(818,631)),
}
res={}
for name,(a,b) in paths.items():
 path=astar(a,b); pts=resample(path,10)
 rows=[]
 for x,y in pts:
  # local max distance to mask around smoothed skeleton point
  xi,yi=int(round(x)),int(round(y)); radius=float(D[yi,xi]);
  rows.append([round(x,1),round(y,1),round(2*radius*.22186,2)])
 res[name]=rows
 print('\n',name,'roots',nearest(a),nearest(b),'path len',round(np.sum(np.linalg.norm(np.diff(path,axis=0),axis=1)),1),'points',rows)
# Overlay sampled centerpaths in cyan
out=im.copy()
for rows in res.values():
 for x,y,_ in rows:
  x,y=int(round(x)),int(round(y)); out[max(0,y-1):y+2,max(0,x-1):x+2]=[0,180,255]
Image.fromarray(out).save('/app/output/target_paths.png')
json.dump(res,open('/app/output/target_paths.json','w'),indent=2)
